'use strict';
const apps=[
 {id:'chat',name:'Yamachat',icon:'yamachat.png',platform:'Windows · Web · Android · iOS PWA',status:'Existující aplikace',description:'Chat, komunity, hlasové hovory a streamování.',detail:'Zdrojový projekt a databázová struktura jsou ověřené. Stávající účet Yamachat zůstává základem společné identity. Uživatel potvrdil funkčnost testovaného hovoru, návratu do Portalu a sdílení obrazovky; další zařízení se ověřují samostatně. Živý web a oficiální stahovací stránka odpověděly HTTP 200. Samostatný web používá vlastní relaci; předání přihlášení z Portalu zatím není implementované.'},
 {id:'search',name:'YamaSearch',icon:'yamasearch.png',platform:'Windows · Android · iOS startovní PWA',status:'Společný účet ve Windows',description:'Samostatný prohlížeč. Windows podporuje volitelný účet Yamaportal.',detail:'Windows verze používá WPF a WebView2. Existují zdroje Android varianty. iOS PWA je startovní stránka otevírající weby externě, nemá vlastní prohlížečové jádro. Windows 0.3.22 přidává volitelný společný účet Yamaportal. Původní účet YamaSearch zůstává dostupný. Android a iOS tímto vydáním společný účet nezískávají. Základní prohlížení zůstane bez povinného účtu.'},
 {id:'help',name:'YamaHelp',icon:'yamahelp.png',platform:'Windows',status:'Existující aplikace',description:'Diagnostika, údržba a nástroje pro Windows.',detail:'Byly nalezeny místní WPF zdroje verze 1.0.86 a aktualizační mechanismus. Oficiální Installer a Portable odpověděly HTTP 200. Veřejný aktualizační zdroj uvádí 1.0.85, místní zdroje 1.0.86. Dostupnost souboru sama nepotvrzuje instalaci ani jeho integritu. Aplikace se bude spouštět samostatně a základní funkce nebudou vyžadovat účet.'},
 {id:'maker',name:'YamaMaker',symbol:'✎',platform:'Platformy zatím nepotvrzené',status:'Připravuje se',description:'Projekt pro tvorbu a úpravu obsahu.',detail:'V dostupných složkách zatím nebyla nalezena zdrojová implementace. Aplikace nemá v Portalu aktivní stažení ani spuštění. Rozsah a platformy doplníme podle skutečných zdrojů.'},
 {id:'view',name:'YamaView',icon:'yamaview.png',platform:'Lokální preview · Windows projekt rozpracovaný',status:'Rozpracováno',description:'Připravované vzdálené ovládání zařízení.',detail:'YamaView má vlastní ikonu a lokální klikací preview se správou zařízení, obrazovkou relace, soubory a chatem. Zobrazená zařízení a spojení jsou simulovaná data. Zdroj obsahuje přípravu Electron aplikace a RustDesk klienta, ale funkční vzdálené spojení, server, podepsaný instalační balíček ani veřejné stažení nejsou ověřené. Portal proto zatím nabízí jen informace; skutečné spuštění nebo stažení doplníme po ověření klienta a serveru.'}
];
let availability=null;
const page=document.querySelector('#page');
const icon=a=>a.icon?`<img class="app-icon" src="assets/${a.icon}" alt="Logo ${a.name}">`:`<span class="app-icon placeholder" aria-hidden="true">${a.symbol}</span>`;
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const primaryAction=a=>a.id==='chat'?'<button class="primary" data-detail="chat">Otevřít Yamachat →</button>':['search','help'].includes(a.id)?'<button class="primary" data-detail="'+a.id+'">Otevřít / stáhnout →</button>':'<span class="coming-soon">Připravuje se</span>';
const cards=(ids=apps.map(a=>a.id))=>'<div class="apps">'+apps.filter(a=>ids.includes(a.id)).map(a=>'<article class="card app-'+a.id+'"><div class="app-head">'+icon(a)+'<div><h3>'+a.name+'</h3><span class="platform">'+a.platform+'</span></div></div><span class="app-status '+(a.status==='Připravuje se'?'pending':'')+'">'+a.status+'</span><p>'+a.description+'</p><div class="card-footer">'+primaryAction(a)+'<button class="card-options" data-detail="'+a.id+'" aria-label="Možnosti aplikace '+a.name+'">Možnosti a informace</button></div></article>').join('')+'</div>';
function renderWelcome(){
 const host=document.querySelector('.hero');if(!host)return;
 const account=YamaAccountUI.dashboardSummary();
 const title=account.signedIn?`Vítej zpět v Yamaportalu,<br><span>${escapeHTML(account.name)}!</span>`:'Vítej v Yamaportalu,<br><span>tvém Yama rozcestníku.</span>';
 const membership=account.memberSince?`<div class="account-fact"><span>Členem od</span><strong>${escapeHTML(account.memberSince)}</strong></div>`:'<div class="account-fact"><span>Profil</span><strong>Údaje z účtu Yamachat</strong></div>';
 const ownerLink=window.YamaAdminUI?.isAdmin()?'<a class="secondary owner-entry" href="#sprava">Správa Yamaportalu →</a>':'';
 const accountPanel=account.signedIn?`<section class="panel account-summary" aria-label="Stav Yama účtu"><div class="summary-profile">${account.avatar}<div><span class="account-active"><i aria-hidden="true"></i>Yama účet aktivní</span><strong>${escapeHTML(account.name)}</strong><span>${escapeHTML(account.email)}</span></div></div><div class="account-facts"><div class="account-fact"><span>Společný profil</span><strong>Yamachat · Yamaportal</strong></div>${membership}</div><a class="primary" href="#profil">⚙ Spravovat účet →</a>${ownerLink}</section>`:`<section class="panel account-summary guest-summary" aria-label="Přihlášení k Yama účtu"><div><span class="account-active inactive"><i aria-hidden="true"></i>Yama účet</span><h2>Všechny aplikace na jednom místě</h2><p>Přihlas se stávajícím účtem Yamachat. Veřejný přehled aplikací je dostupný i bez přihlášení.</p></div><a class="primary" href="#profil">Přihlásit se →</a><button class="secondary" data-account="register">Vytvořit účet</button></section>`;
 host.innerHTML=`<div class="dashboard-intro"><p class="eyebrow">TVŮJ YAMA EKOSYSTÉM</p><h1>${title}</h1><p>Jeden Yama účet. Všechny tvoje aplikace na jednom místě.<br>Yamachat, YamaHelp, YamaSearch a další samostatné aplikace.</p></div>${accountPanel}`;
}
const names={stazeni:'Stažení Yamaportalu',consent:'Propojení YamaSearch',yamachat:'Yamachat',sprava:'Správa Yamaportalu',domu:'Domů',aplikace:'Aplikace',profil:'Můj profil',propojeni:'Propojení',nastaveni:'Nastavení',aktualizace:'Aktualizace','live-chat':'Živý chat',forum:'Fórum'};
function renderPage(){const route=location.hash.slice(1)||'domu';const active=Object.hasOwn(names,route)?route:'domu';document.querySelectorAll('nav a').forEach(a=>{const selected=a.hash==='#'+active;a.classList.toggle('active',selected);if(selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});renderWelcome();
 page.hidden=active==='yamachat';if(active==='yamachat'){void YamaModuleHost.show();return;}YamaModuleHost.hide();
 if(active==='sprava'){page.innerHTML=YamaAdminUI.markup();void YamaAdminUI.load();return;}
 if(active==='consent'){void YamaConsent.show();return;}
 if(active==='live-chat'||active==='forum'){YamaPortalCommunity.show(active);return;}
 if(active==='domu')page.innerHTML=`<div class="dashboard-grid"><section class="panel catalog"><div class="catalog-heading"><div><p class="eyebrow">TVOJE APLIKACE</p><h2>Tvůj prostor. Tvoje aplikace.</h2><p class="muted">Pokračuj tam, kde chceš. Každá aplikace si zachovává vlastní funkce.</p></div><a class="secondary" href="#aplikace">Všechny aplikace →</a></div>${cards(['chat','search','help'])}</section><aside class="dashboard-side"><section class="panel quick-panel"><p class="eyebrow">ϟ &nbsp; RYCHLÝ PŘÍSTUP</p><button class="quick-action quick-chat" data-detail="chat"><span aria-hidden="true">▣</span>Otevřít Yamachat <b aria-hidden="true">›</b></button><button class="quick-action quick-search" data-detail="search"><span aria-hidden="true">⌕</span>Možnosti YamaSearch <b aria-hidden="true">›</b></button><button class="quick-action quick-help" data-detail="help"><span aria-hidden="true">⚒</span>Možnosti YamaHelp <b aria-hidden="true">›</b></button></section><section class="panel activity-panel"><p class="eyebrow">◷ &nbsp; POSLEDNÍ AKTUALIZACE</p><div class="release-feed" id="release-feed" aria-live="polite"><p class="activity-empty"><span aria-hidden="true">◷</span>Načítám ověřená vydání…</p></div><a class="activity-more" href="#aktualizace">Všechny informace o aktualizacích →</a></section></aside></div><div class="portal-community-grid"><section class="panel community-card"><div class="community-card-heading"><span class="community-symbol chat-symbol" aria-hidden="true">◉</span><div><p class="eyebrow">POUZE PRO PŘIHLÁŠENÉ</p><h2>Živý chat</h2></div></div><p>Připoj se k ostatním uživatelům Yamaportalu v krátké společné konverzaci.</p><a class="primary" href="#live-chat">Otevřít živý chat →</a></section><section class="panel community-card forum-card"><div class="community-card-heading"><span class="community-symbol forum-symbol" aria-hidden="true">▤</span><div><p class="eyebrow">POUZE PRO PŘIHLÁŠENÉ</p><h2>Fórum</h2></div></div><p>Zakládej témata, prohlížej přehled a zapoj se do diskuse komunity.</p><a class="primary" href="#forum">Otevřít fórum →</a></section></div><section class="portal-download-banner"><div><h2>Yamaportal pro tvé zařízení</h2><p>Windows aplikace nebo instalovatelný web na mobilu.</p></div><a class="primary" href="#stazeni">Stáhnout / nainstalovat →</a></section>`;
 if(active==='domu')void window.YamaReleaseFeed?.render();
 if(active==='aplikace')page.innerHTML=`<section class="panel catalog"><h2>Všechny Yama aplikace</h2><p class="muted">Ověřené oficiální odkazy. Přihlašování a možnosti jednotlivých platforem se ověřují samostatně.</p>${cards()}</section>`;
 if(active==='stazeni'){page.innerHTML='<section class="panel page-content"><h2>Stáhnout Yamaportal</h2><div id="portal-download-list"><p>Ověřuji dostupné balíčky…</p></div>'+YamaPortalPWA.markup()+'</section>';void YamaDownloads.render();}
 if(active==='profil')page.innerHTML=YamaAccountUI.profilePage();
 if(active==='propojeni')page.innerHTML=YamaAccountUI.connections();
 if(active==='nastaveni')page.innerHTML=`<section class="panel page-content"><h2>Nastavení Yamaportalu</h2><p class="muted">Tyto volby fungují lokálně v tomto prohlížeči.</p><label class="settings-row"><span>Rozložení rozhraní</span><select id="layout"><option value="web">Horní navigace</option><option value="windows">Boční navigace</option></select></label><label class="settings-row"><span>Hustota zobrazení</span><select id="density"><option value="comfortable">Pohodlné</option><option value="compact">Kompaktní</option></select></label>${YamaPortalPWA.markup()}<div class="notice"><strong>Otevírání a zabezpečení aplikací</strong>Na počítači můžeš zvolit horní nebo boční navigaci. Mobil používá horní menu. Windows aplikaci stáhneš v sekci Stažení Yamaportalu.</div><button class="secondary" id="reset">Obnovit výchozí vzhled</button><p id="saved" role="status" class="caption"></p></section>`;
 if(active==='aktualizace'){page.innerHTML='<section class="panel page-content"><h2>Aktualizace Yamaportalu</h2><p>Aktualizace si stáhneš z ověřeného distribučního zdroje a spustíš ručně. Soubory nejsou podepsané. Web a PWA načtou novou verzi při připojení k internetu.</p><div id="portal-download-list"><p>Ověřuji dostupné balíčky…</p></div><p class="caption">Ostatní samostatné aplikace používají své vlastní aktualizace. YamaMaker a YamaView se připravují.</p></section>';void YamaDownloads.render();}
 if(active==='nastaveni'){document.querySelector('#layout').value=prefs.mode;document.querySelector('#density').value=prefs.density;document.querySelector('#layout').onchange=e=>update({mode:e.target.value});document.querySelector('#density').onchange=e=>update({density:e.target.value});document.querySelector('#reset').onclick=()=>{update({mode:'web',density:'comfortable'});render();};}
}
function render(){try{renderPage();}catch{page.hidden=false;page.innerHTML='<section class="panel"><h2>Stránku se nepodařilo načíst</h2><p>Obnov stránku nebo se vrať na přehled aplikací.</p><a class="secondary" href="#domu">Přehled aplikací</a></section>';}}
let prefs={mode:'web',density:'comfortable'};try{const saved=JSON.parse(localStorage.getItem('yamaportal-preview-preferences'));if(saved&&['web','windows'].includes(saved.mode))prefs.mode=saved.mode;if(saved&&['comfortable','compact'].includes(saved.density))prefs.density=saved.density;}catch{}
function update(next){Object.assign(prefs,next);document.body.classList.toggle('windows',prefs.mode==='windows');document.body.classList.toggle('compact',prefs.density==='compact');document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===prefs.mode)));let message='Vzhled je uložený v tomto prohlížeči.';try{localStorage.setItem('yamaportal-preview-preferences',JSON.stringify(prefs));}catch{message='Vzhled se změnil. Prohlížeč nepovolil jeho uložení.';}const status=document.querySelector('#saved');if(status)status.textContent=message;const select=document.querySelector('#layout');if(select)select.value=prefs.mode;}
document.addEventListener('click',e=>{const mode=e.target.closest('[data-mode]');if(mode)update({mode:mode.dataset.mode});const route=e.target.closest('[data-route]');if(route)location.hash=route.dataset.route;const button=e.target.closest('[data-detail]');if(button){const a=apps.find(x=>x.id===button.dataset.detail);document.querySelector('#detail-content').innerHTML=`${icon(a)}<h2>${a.name}</h2><span class="pill">${a.status}</span><p>${a.detail}</p><p class="caption">${a.platform}</p>${YamaAppLinks.markup(availability,a.id)}`;document.querySelector('#detail').showModal();}if(e.target.closest('.close,.close-detail'))document.querySelector('#detail').close();});
if(new URL(location.href).searchParams.has('authorization_id'))location.hash='consent';
window.addEventListener('hashchange',render);update({});render();

document.addEventListener('yama-account-state',()=>{void YamaAdminUI.init();if(YamaAccountUI.shouldRender())render();});
window.addEventListener('yama-admin-state',()=>{if(['domu','sprava'].includes(location.hash.slice(1)||'domu'))render();});
window.addEventListener('hashchange',()=>YamaAccountUI.clearDirty());
void YamaAccountUI.init();
void YamaAdminUI.init();





fetch('app-availability.json',{cache:'no-store'}).then(response=>response.ok?response.json():null).then(report=>{availability=report;if(['domu','aplikace','aktualizace',''].includes(location.hash.slice(1))&&YamaAccountUI.shouldRender())render();}).catch(()=>{});
document.addEventListener('yama-native-state',()=>{if(['domu','aplikace',''].includes(location.hash.slice(1)))render();});
